Here is the commit message:
ASoC: AMD: free memory on error

Static checkers complain if we don't free "adata" before returning.

Fixes: 7c31335a03b6 ('ASoC: AMD: add AMD ASoC ACP 2.x DMA driver')
Signed-off-by: Dan Carpenter <dan.carpenter@oracle.com>
Signed-off-by: Mark Brown <broonie@kernel.org>

Here is the root cause:
The bug arises from the lack of proper memory management in the `acp_dma_open` function, where the allocated memory for `adata` is not freed if an error occurs during the execution of the function. This oversight can lead to memory leaks, as the allocated memory remains inaccessible and unfreed when the function exits prematurely due to an error.

Here is the patch:

 static int acp_dma_open(struct snd_pcm_substream *substream)
 {
 	u16 bank;
 	int ret = 0;
 	struct snd_pcm_runtime *runtime = substream->runtime;
 	struct snd_soc_pcm_runtime *prtd = substream->private_data;
 	struct audio_drv_data *intr_data = dev_get_drvdata(prtd->platform->dev);

 	struct audio_substream_data *adata =
 		kzalloc(sizeof(struct audio_substream_data), GFP_KERNEL);
 	if (adata == NULL)
 		return -ENOMEM;

 	if (substream->stream == SNDRV_PCM_STREAM_PLAYBACK)
 		runtime->hw = acp_pcm_hardware_playback;
 	else
 		runtime->hw = acp_pcm_hardware_capture;

 	ret = snd_pcm_hw_constraint_integer(runtime,
 					    SNDRV_PCM_HW_PARAM_PERIODS);
 	if (ret < 0) {
 		dev_err(prtd->platform->dev, "set integer constraint failed\n");
+		kfree(adata);
 		return ret;
 	}

 	adata->acp_mmio = intr_data->acp_mmio;
 	runtime->private_data = adata;

 	/* Enable ACP irq, when neither playback or capture streams are
 	 * active by the time when a new stream is being opened.
 	 * This enablement is not required for another stream, if current
 	 * stream is not closed
 	*/
 	if (!intr_data->play_stream && !intr_data->capture_stream)
 		acp_reg_write(1, adata->acp_mmio, mmACP_EXTERNAL_INTR_ENB);

 	if (substream->stream == SNDRV_PCM_STREAM_PLAYBACK) {
 		intr_data->play_stream = substream;
 		for (bank = 1; bank <= 4; bank++)
 			acp_set_sram_bank_state(intr_data->acp_mmio, bank,
 						true);
 	} else {
 		intr_data->capture_stream = substream;
 		for (bank = 5; bank <= 8; bank++)
 			acp_set_sram_bank_state(intr_data->acp_mmio, bank,
 						true);
 	}

 	return 0;
 }



